function asString(value, fallback = '') {
  if (typeof value === 'string') return value;

  if (
    typeof value === 'number' ||
    typeof value === 'boolean'
  ) {
    return String(value);
  }

  // Não serializar objetos arbitrários:
  // podem conter headers, payloads ou credentials.
  return fallback;
}

function basicRedact(value) {
  let text = asString(value);

  // URLs de banco com usuário/senha.
  text = text.replace(
    /\b(?:postgres(?:ql)?|mysql|mariadb):\/\/[^\s]+/gi,
    '[REDACTED_DB_URL]'
  );

  // Authorization Bearer / Basic.
  text = text.replace(
    /\b(Bearer|Basic)\s+[A-Za-z0-9._~+\/=-]+/gi,
    '$1 [REDACTED]'
  );

  // Tokens GitHub clássicos / fine-grained.
  text = text.replace(
    /\b(?:github_pat_|gh[pousr]_)[A-Za-z0-9_]{10,}/gi,
    '[REDACTED_GITHUB_TOKEN]'
  );

  // Campos comuns de segredo.
  text = text.replace(
    /\b(authorization|token|password|passwd|pwd|secret|api[_-]?key|access[_-]?token|refresh[_-]?token)\b\s*[:=]\s*["']?[^,\s;}"']+/gi,
    '$1=[REDACTED]'
  );

  return text;
}

function parseSafeEnvelope(message) {
  const marker = 'P01_SAFE_ERROR:';

  const index = message.indexOf(marker);

  if (index === -1) {
    return {};
  }

  const candidate = message
    .slice(index + marker.length)
    .split('\n')[0]
    .trim();

  try {
    const parsed = JSON.parse(candidate);

    if (
      parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
    ) {
      return parsed;
    }
  } catch {
    // Ignora envelope inválido.
  }

  return {};
}

function normalizeStatus(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === '') {
      continue;
    }

    const n = Number(value);

    if (
      Number.isInteger(n) &&
      n >= 100 &&
      n <= 599
    ) {
      return n;
    }
  }

  return null;
}

function normalizeBoolean(value) {
  if (typeof value === 'boolean') return value;

  if (typeof value === 'string') {
    if (value.toLowerCase() === 'true') return true;
    if (value.toLowerCase() === 'false') return false;
  }

  return null;
}

function classifyError({
  explicitCategory,
  message,
  status,
  nodeName,
