  if (ALLOWED_CATEGORIES.has(explicitCategory)) {
    return explicitCategory;
  }

  const m = `${message ?? ''}`.toLowerCase();
  const node = `${nodeName ?? ''}`.toLowerCase();

  if (
    /page.?limit|max.?pages|pagination.?limit/.test(m)
  ) {
    return 'page_limit';
  }

  if (
    /schema|migration|relation .* does not exist|column .* does not exist/.test(m)
  ) {
    return 'schema';
  }

  if (
    /concurr|deadlock|already running|lock timeout/.test(m)
  ) {
    return 'concurrency';
  }

  if (
    status === 401 ||
    /bad credentials|invalid token|authentication failed/.test(m)
  ) {
    return 'authentication';
  }

  if (
    status === 429 ||
    /rate.?limit|secondary.?rate.?limit|abuse.?limit/.test(m)
  ) {
    return 'rate_limit';
  }

  if (status === 403) {
    return 'authorization';
  }

  if (
    status === 408 ||
    status === 504 ||
    /timeout|timed out|etimedout/.test(m)
  ) {
    return 'timeout';
  }

  if (
    node.includes('postgres') ||
    node.includes('database') ||
    /\bsqlstate\b/.test(m)
  ) {
    return 'database';
  }

  if (
    /enotfound|econnreset|econnrefused|eai_again|socket hang up|network error/.test(m)
  ) {
    return 'network';
  }

  if (
    status !== null &&
    status >= 500 &&
    status <= 599
  ) {
    return 'github_server';
  }

  if (
    status === 400 ||
    status === 422 ||
    /validation|invalid payload|required field/.test(m)
  ) {
    return 'validation';
  }

  return 'unexpected';
