  safeEnvelope.githubRequestId ??
  err.context?.github_request_id ??
  err.context?.githubRequestId ??
  responseHeaders?.['x-github-request-id'] ??
  responseHeaders?.['X-GitHub-Request-Id'] ??
  null;


